<?php
require_once __DIR__.'/../includes/bootstrap.php';require_admin();
if($_SERVER['REQUEST_METHOD']!=='POST'){header('Location: reports.php');exit;}
verify_csrf();$saleId=(int)($_POST['sale_id']??0);$reason=trim((string)($_POST['reason']??''));
if($saleId<1||$reason===''){header('Location: reports.php');exit;}
$pdo=db();
try{$pdo->beginTransaction();$get=$pdo->prepare('SELECT * FROM sales WHERE id=? FOR UPDATE');$get->execute([$saleId]);$sale=$get->fetch();if(!$sale||!empty($sale['is_void']))throw new RuntimeException('Sale is unavailable.');
$items=$pdo->prepare('SELECT product_id,qty FROM sale_items WHERE sale_id=?');$items->execute([$saleId]);$stock=$pdo->prepare('UPDATE products SET stock_qty=stock_qty+? WHERE id=?');$move=$pdo->prepare("INSERT INTO stock_movements(product_id,user_id,movement_type,qty,note,reference_no) VALUES(?,?,'adjustment',?,?,?)");foreach($items as $item){if($item['product_id']!==null){$stock->execute([$item['qty'],$item['product_id']]);$move->execute([$item['product_id'],auth_user()['id'],$item['qty'],'Void sale: '.$reason,$sale['bill_no']]);}}
$used=$pdo->prepare("SELECT consumable_id,-SUM(qty) restore_qty FROM consumable_movements WHERE sale_id=? AND movement_type='sale' GROUP BY consumable_id");$used->execute([$saleId]);$restoreConsumable=$pdo->prepare('UPDATE consumables SET stock_qty=stock_qty+? WHERE id=?');$logConsumable=$pdo->prepare("INSERT INTO consumable_movements(consumable_id,user_id,sale_id,movement_type,qty,note,reference_no) VALUES(?,?,?,'reversal',?,'Void sale consumable reversal',?)");foreach($used as $consumable){$qty=(float)$consumable['restore_qty'];if($qty>0){$restoreConsumable->execute([$qty,$consumable['consumable_id']]);$logConsumable->execute([$consumable['consumable_id'],auth_user()['id'],$saleId,$qty,$sale['bill_no']]);}}
$void=$pdo->prepare('UPDATE sales SET is_void=1,void_reason=?,voided_by=?,voided_at=NOW() WHERE id=?');$void->execute([$reason,auth_user()['id'],$saleId]);$pdo->commit();log_activity('Bill Voided','sales','Bill '.$sale['bill_no'].' • LKR '.number_format((float)$sale['total'],2).' • Reason: '.$reason,$saleId);$_SESSION['flash']='Sale voided and product/packaging stock restored.';}catch(Throwable $e){if($pdo->inTransaction())$pdo->rollBack();error_log('Void sale failure: '.$e->getMessage());$_SESSION['flash']='Could not void the sale. No stock was changed.';}
header('Location: reports.php');exit;
